// 来源：beUI <https://beui.dev/r/returns-calendar.json>，上游文件 components/charts/returns-calendar.tsx
// 许可证：MIT © 2026 Saurabh Chauhan <https://github.com/starc007/ui-components/blob/main/LICENSE>
